import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String[] args) throws Exception
    {
        InputStreamReader isr = new InputStreamReader(System.in);
        BufferedReader br = new BufferedReader(isr);
        String[] inputLine = br.readLine().split(" ");
        int totalCount = Integer.parseInt(inputLine[0]);
        double probabilityThreshold = Double.parseDouble(inputLine[1]);
        int answer;
        for(answer=0; answer<=totalCount; answer++)
        {
            if(probabilityCheck(totalCount, answer) >= probabilityThreshold) break;
        }
        System.out.println(answer);
        br.close();
    }

    static int ncr(int n, int r)
    {
        if(r > n) return 0;
        int res=1;
        for(int i=n; i>n-r; i--) res*=i;
        for(int i=2; i<=r; i++) res/=i;
        return res;
    }

    static double probabilityCheck(int n, int x)
    {
        int a = ncr(x, 3) * ncr(n - x, 0);
        int b = ncr(x, 2) * ncr(n - x, 1);
        int c = ncr(x, 1) * ncr(n - x, 2);
        return ((3.0/6)*c + a + b) / ncr(n, 3);
    }
}
